import requests
import json

headers = {
    'Authorization': 'Bearer YOUR_API_KEY'
}

url = 'https://api.va.landing.ai/v1/ade/parse'

# Set the model (optional)
data = {
    'model': 'dpt-2-latest'
}

# Upload a document 
document = open('document.pdf', 'rb')
files = {'document': document}

response = requests.post(url, files=files, data=data, headers=headers)
print(response.json())

const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');

const form = new FormData();
form.append('document', fs.createReadStream('document.pdf'));

// Set the model (optional)
form.append('model', 'dpt-2-latest');

axios.post('https://api.va.landing.ai/v1/ade/parse', form, {
  headers: {
    'Authorization': 'Bearer YOUR_API_KEY',
    ...form.getHeaders()
  }
})
.then(response => console.log(response.data))
.catch(error => console.error(error));

const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');

const form = new FormData();
form.append('markdown', fs.createReadStream('markdown.md'));
form.append('schema', fs.readFileSync('schema.json', 'utf8'));
form.append('model', 'extract-latest');

axios.post('https://api.va.landing.ai/v1/ade/extract', form, {
  headers: {
    'Authorization': 'Bearer YOUR_API_KEY',
    ...form.getHeaders()
  }
})
.then(response => console.log(response.data))
.catch(error => console.error(error));

